75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /**
81	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
82	     * owner's id, customer code, registration date and membership level, so the create side-effect
83	     * can be audited independently of the application log.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    /**
96	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
97	     * and a domain containing at least one dot, with no whitespace in any segment.
98	     */
99	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
100	
101	    /**
102	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
103	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
104	     * {@code '@'}) is rejected with a 400 Bad Request.
105	     */
106	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
107	        "mailinator.com",
108	        "tempmail.com",
109	        "guerrillamail.com");
110	
111	    /**
112	     * Required national-number length per E.164 country code. A normalized telephone whose country
113	     * code appears here must carry exactly this many national digits after the code; Australia
114	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
115	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
116	     */
117	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
118	
119	    /**
120	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
121	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
122	     */
123	    private static final int MAX_OWNERS_PER_CITY = 50;
124	
125	    /**
126	     * Maximum number of owners that may be registered on a single day (by registration date). A create
127	     * attempted once this many owners already carry today's registration date is rejected with a
128	     * 429 Too Many Requests.
129	     */
130	    private static final int MAX_OWNERS_PER_DAY = 100;
131	
132	    /**
133	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
134	     * owners already carry the new owner's registration date, the created owner is flagged
135	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
136	     */
137	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
138	
139	    /**
140	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
141	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
142	     */
143	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
144	        "ST", "STREET",
145	        "RD", "ROAD",
146	        "AVE", "AVENUE");
147	
148	    /**
149	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
150	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
151	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
152	     * 4-digit postcode.
153	     */
154	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
155	        "NSW", new int[] {2000, 2099},
156	        "VIC", new int[] {3000, 3099},
157	        "QLD", new int[] {4000, 4099});
158	
159	    /**
160	     * Name of the request header that carries the client-supplied idempotency key for an owner create.
161	     * When a create repeats with a key already seen, the originally created owner is returned with
162	     * {@code 200 OK} instead of a second owner being created.
163	     */
164	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
165	
166	    /**
167	     * Remembers, per idempotency key, the id of the owner created by the first request that carried that
168	     * key, so a later create repeating the same key can return the original owner instead of creating a
169	     * duplicate. The key space is the client-supplied {@code Idempotency-Key} header value.
170	     */
171	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
172	
173	    public OwnerRestControllerV1(ClinicService clinicService,
174	                                 OwnerMapper ownerMapper,
175	                                 PetMapper petMapper,
176	                                 VisitMapper visitMapper) {
177	        this.clinicService = clinicService;
178	        this.ownerMapper = ownerMapper;
179	        this.petMapper = petMapper;
180	        this.visitMapper = visitMapper;
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
186	        Collection<Owner> owners;
187	        if (lastName != null) {
188	            owners = this.clinicService.findOwnerByLastName(lastName);
189	        } else {
190	            owners = this.clinicService.findAllOwners();
191	        }
192	        if (owners.isEmpty()) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner == null) {
203	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	        }
205	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
211	        String idempotencyKey = currentIdempotencyKey();
212	        OwnerDto replayed = replayIfSeen(idempotencyKey);
213	        if (replayed != null) {
214	            return new ResponseEntity<>(replayed, HttpStatus.OK);
215	        }
216	        validateRequiredFields(ownerFieldsDto);
217	        HttpHeaders headers = new HttpHeaders();
218	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
219	        rejectFutureRegistrationDate(owner.getRegistrationDate());
220	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
221	        owner.setRegistrationDate(registrationDate);
222	        requireDailyCapacity(registrationDate);
223	        requireCityHasCapacity(owner.getCity());
224	        validatePostcode(owner);
225	        applyAddress(owner, ownerFieldsDto);
226	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
227	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
228	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
229	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
230	        requireUniqueIdentity(owner);
231	        flagPossibleDuplicate(owner, declaredHouseholdMember);
232	        owner.setCustomerCode(deduplicateCustomerCode(owner.buildCustomerCode()));
233	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
234	        stampHouseholdSize(owner);
235	        capMembershipLevelToHousehold(owner);
236	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
237	        this.clinicService.saveOwner(owner);
238	        rememberCreate(idempotencyKey, owner);
239	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
240	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
241	            owner.getMembershipNumber());
242	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
243	        headers.setLocation(UriComponentsBuilder.newInstance()
244	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
245	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
246	    }
247	
248	    /**
249	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
250	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
251	     * or when no servlet request is bound to the current thread.
252	     *
253	     * <p>The header is read from the bound request rather than taken as a {@code @RequestHeader} method
254	     * parameter because {@code addOwner}'s signature is fixed by the generated {@link OwnersApi}
255	     * interface and cannot carry an extra parameter.
256	     *
257	     * @return the trimmed idempotency key, or {@code null} when none was supplied
258	     */
259	    private String currentIdempotencyKey() {
260	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
261	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
262	            if (StringUtils.hasText(key)) {
263	                return key.trim();
264	            }
265	        }
266	        return null;
267	    }
268	
269	    /**
270	     * Returns the owner originally created under the given idempotency key, so a create repeating a
271	     * key already seen replays the first result instead of creating a duplicate. Yields {@code null}
272	     * when there is no key, the key has not been seen, or the remembered owner no longer exists (in
273	     * which case the create proceeds normally).
274	     *
275	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
276	     * @return the originally created owner as a DTO, or {@code null} when there is nothing to replay
277	     */
278	    private OwnerDto replayIfSeen(String idempotencyKey) {
279	        if (idempotencyKey == null) {
280	            return null;
281	        }
282	        Integer existingId = idempotentCreates.get(idempotencyKey);
283	        if (existingId == null) {
284	            return null;
285	        }
286	        Owner existing = this.clinicService.findOwnerById(existingId);
287	        return existing == null ? null : ownerMapper.toOwnerDto(existing);
288	    }
289	
290	    /**
291	     * Remembers the id of a just-created owner against the idempotency key that produced it, so a later
292	     * create repeating the same key can be replayed by {@link #replayIfSeen}. A {@code null} key (the
293	     * create was not idempotent) is ignored.
294	     *
295	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
296	     * @param owner the owner that was just created and saved
297	     */
298	    private void rememberCreate(String idempotencyKey, Owner owner) {
299	        if (idempotencyKey != null) {
300	            idempotentCreates.put(idempotencyKey, owner.getId());
301	        }
302	    }
303	
304	    /**
305	     * Rejects a create whose supplied registration date is later than the server's current date. A
306	     * registration may be back-dated but never post-dated, so a future date is treated as a client
307	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
308	     * server date.
309	     *
310	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
311	     *     client omitted it
312	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
313	     */
314	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
315	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
316	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
317	        }
318	    }
319	
320	    /**
321	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
322	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
323	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
324	     * existed prior to this create.
325	     *
326	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
327	     *     a business day
328	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
329	     *     registered on that business day
330	     */
331	    private void requireDailyCapacity(LocalDate registrationDate) {
332	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
333	            throw new DailyOwnerLimitException(registrationDate);
334	        }
335	    }
336	
337	    /**
338	     * Counts the existing owners whose registration date equals the given business-day date. This is
339	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
340	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
341	     * the bulk-signup warning.
342	     *
343	     * @param registrationDate the effective business-day registration date to count against
344	     * @return the number of pre-existing owners registered on that date
345	     */
346	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
347	        return this.clinicService.findAllOwners().stream()
348	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
349	            .count();
350	    }
351	
352	    /**
353	     * Rejects an owner whose city already contains the maximum allowed number of owners
354	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
355	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
356	     * create.
357	     *
358	     * @param city the city of the owner being created
359	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
360	     */
361	    private void requireCityHasCapacity(String city) {
362	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
363	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
364	            .count();
365	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
366	            throw new CityOwnerLimitException(city);
367	        }
368	    }
369	
370	    /**
371	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
372	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
373	     * schema) that must fall within the inclusive range permitted for the region derived from the
374	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
375	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
376	     *
377	     * @param owner the owner being created, with its city and postcode set
378	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
379	     */
380	    private void validatePostcode(Owner owner) {
381	        String postcode = owner.getPostcode();
382	        if (postcode == null) {
383	            return;
384	        }
385	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
386	        if (range == null) {
387	            return;
388	        }
389	        int value = Integer.parseInt(postcode);
390	        if (value < range[0] || value > range[1]) {
391	            throw new InvalidOwnerFieldsException(List.of("postcode"));
392	        }
393	    }
394	
395	    /**
396	     * Counts the existing owners that already share the given first name and last name, compared
397	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
398	     * owners that existed prior to this create.
399	     *
400	     * @param firstName the first name of the owner being created
401	     * @param lastName the last name of the owner being created
402	     * @return the number of pre-existing namesakes
403	     */
404	    private int countNamesakes(String firstName, String lastName) {
405	        return (int) this.clinicService.findAllOwners().stream()
406	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
407	                && equalsIgnoreCase(existing.getLastName(), lastName))
408	            .count();
409	    }
410	
411	    /**
412	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
413	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
414	     *
415	     * @param a the first value, possibly {@code null}
416	     * @param b the second value, possibly {@code null}
417	     * @return whether the values are equal ignoring case
418	     */
419	    private boolean equalsIgnoreCase(String a, String b) {
420	        return a == null ? b == null : a.equalsIgnoreCase(b);
421	    }
422	
423	    /**
424	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
425	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
426	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
427	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
428	     *
429	     * @param ownerFieldsDto the submitted owner fields
430	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
431	     */
432	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
433	        List<String> invalidFields = new ArrayList<>();
434	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
435	            invalidFields.add("firstName");
436	        }
437	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
438	            invalidFields.add("lastName");
439	        }
440	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddressLine1()))
441	            && !StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
442	            invalidFields.add("address");
443	        }
444	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
445	            invalidFields.add("city");
446	        }
447	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
448	            invalidFields.add("telephone");
449	        }
450	        if (!invalidFields.isEmpty()) {
451	            throw new InvalidOwnerFieldsException(invalidFields);
452	        }
453	    }
454	
455	    /**
456	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
457	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
458	     * what gets stored and returned.
459	     *
460	     * @param telephone the raw telephone value from the request
461	     * @return the normalized E.164 telephone number
462	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
463	     */
464	    private String normalizeTelephone(String telephone) {
465	        String e164 = toE164(telephone);
466	        if (e164 == null) {
467	            throw new InvalidOwnerFieldsException(List.of("telephone"));
468	        }
469	        return e164;
470	    }
471	
472	    /**
473	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
474	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
475	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
476	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
477	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
478	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
479	     *
480	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
481	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
482	     *
483	     * @param telephone the raw telephone value, possibly {@code null}
484	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
485	     */
486	    private String toE164(String telephone) {
487	        if (telephone == null) {
488	            return null;
489	        }
490	        String cleaned = telephone.replaceAll("[ \\-()]", "");
491	        String digits;
492	        if (cleaned.startsWith("+")) {
493	            digits = cleaned.substring(1);
494	        } else {
495	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
496	            digits = "61" + national;
497	        }
498	        if (!digits.matches("[0-9]{8,15}")) {
499	            return null;
500	        }
501	        if (!nationalNumberLengthValid(digits)) {
502	            return null;
503	        }
504	        return "+" + digits;
505	    }
506	
507	    /**
508	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
509	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
510	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
511	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
512	     * accepted, leaving only the generic total-length rule to apply.
513	     *
514	     * @param digits the E.164 digits without the leading {@code '+'}
515	     * @return {@code true} if the national-number length matches the country code's requirement
516	     */
517	    private boolean nationalNumberLengthValid(String digits) {
518	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
519	            String code = entry.getKey();
520	            if (digits.startsWith(code)) {
521	                return digits.length() - code.length() == entry.getValue();
522	            }
523	        }
524	        return true;
525	    }
526	
527	    /**
528	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
529	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
530	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
531	     * returned lower-cased.
532	     *
533	     * @param email the raw email value from the request, possibly {@code null}
534	     * @return the lower-cased email, or {@code null} when none was supplied
535	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
536	     *     its domain is on the disposable-domain blocklist
537	     */
538	    private String normalizeEmail(String email) {
539	        if (!StringUtils.hasText(email)) {
540	            return null;
541	        }
542	        String trimmed = email.trim();
543	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
544	            throw new InvalidOwnerFieldsException(List.of("email"));
545	        }
546	        String normalized = trimmed.toLowerCase(Locale.ROOT);
547	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
548	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
549	            throw new InvalidOwnerFieldsException(List.of("email"));
550	        }
551	        return normalized;
552	    }
553	
554	    /**
555	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
556	     * This is the single consolidated duplicate check: the identity key
557	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
558	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
559	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
560	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
561	     * but carrying different telephones have different identity keys and are both allowed (the second
562	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
563	     *
564	     * @param owner the owner being created, with its normalized telephone, email and last name set
565	     * @throws DuplicateIdentityException if another owner already has this identity key
566	     */
567	    private void requireUniqueIdentity(Owner owner) {
568	        String identityKey = owner.getIdentityKey();
569	        boolean inUse = this.clinicService.findAllOwners().stream()
570	            .filter(existing -> !existing.isDeleted())
571	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
572	        if (inUse) {
573	            throw new DuplicateIdentityException(identityKey);
574	        }
575	    }
576	
577	    /**
578	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
579	     * When the computed code is unique it is returned unchanged. When it collides with an existing
580	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
581	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
582	     * so on), and that de-duplicated code is returned.
583	     *
584	     * @param customerCode the freshly computed customer code to de-duplicate
585	     * @return a customer code not held by any existing owner
586	     */
587	    private String deduplicateCustomerCode(String customerCode) {
588	        Set<String> inUse = this.clinicService.findAllOwners().stream()
589	            .map(Owner::getCustomerCode)
590	            .filter(Objects::nonNull)
591	            .collect(Collectors.toSet());
592	        if (!inUse.contains(customerCode)) {
593	            return customerCode;
594	        }
595	        int n = 2;
596	        String candidate;
597	        do {
598	            candidate = customerCode + "-" + n;
599	            n++;
600	        } while (inUse.contains(candidate));
601	        return candidate;
602	    }
603	
604	    /**
605	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
606	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
607	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
608	     * (both present and equal) while carrying a different identity key. When such an existing owner is
609	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
610	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
611	     * is false and {@code possibleDuplicateOf} is left unset.
612	     *
613	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
614	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
615	     *
616	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
617	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
618	     */
619	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
620	        if (declaredHouseholdMember || owner.getPostcode() == null) {
621	            owner.setPossibleDuplicate(false);
622	            return;
623	        }
624	        String identityKey = owner.getIdentityKey();
625	        String soundex = Soundex.encode(owner.getLastName());
626	        Integer matchId = this.clinicService.findAllOwners().stream()
627	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
628	                && owner.getPostcode().equals(existing.getPostcode())
629	                && !identityKey.equals(existing.getIdentityKey()))
630	            .map(Owner::getId)
631	            .min(Integer::compareTo)
632	            .orElse(null);
633	        owner.setPossibleDuplicate(matchId != null);
634	        owner.setPossibleDuplicateOf(matchId);
635	    }
636	
637	    /**
638	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
639	     * the household - the existing owners that share the deterministic {@code householdId} and the new
640	     * one - so the shared size can be read back from any of them. The count is the number of existing
641	     * members plus the owner being created.
642	     *
643	     * @param owner the owner being created, with its deterministic {@code householdId} already set
644	     */
645	    private void stampHouseholdSize(Owner owner) {
646	        List<Owner> members = householdMembers(owner);
647	        int householdSize = members.size() + 1;
648	        owner.setHouseholdSize(householdSize);
649	        for (Owner member : members) {
650	            member.setHouseholdSize(householdSize);
651	            this.clinicService.saveOwner(member);
652	        }
653	    }
654	
655	    /**
656	     * The existing owners that belong to the same household as the given owner - those that share its
657	     * deterministic {@code householdId}. This is the single definition of "who is in this household",
658	     * shared by the household-size stamp and the membership-level cap. The owner being created is not
659	     * among them (it has not been saved yet); soft-deleted owners are included, so callers that need
660	     * only live members filter them out themselves.
661	     *
662	     * @param owner the owner being created, with its deterministic {@code householdId} already set
663	     * @return the existing same-household owners
664	     */
665	    private List<Owner> householdMembers(Owner owner) {
666	        String householdId = owner.getHouseholdId();
667	        return this.clinicService.findAllOwners().stream()
668	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
669	            .toList();
670	    }
671	
672	    /**
673	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
674	     * membership level among the existing members of its household - the non-deleted owners that share
675	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
676	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
677	     * has no existing member no cap applies and the level is left untouched.
678	     *
679	     * @param owner the owner being created, with its deterministic {@code householdId} and
680	     *     {@code householdSize} already set
681	     */
682	    private void capMembershipLevelToHousehold(Owner owner) {
683	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
684	            .filter(existing -> !existing.isDeleted())
685	            .mapToInt(Owner::getMembershipLevel)
686	            .max();
687	        if (maxMemberLevel.isEmpty()) {
688	            return;
689	        }
690	        int cap = maxMemberLevel.getAsInt() + 1;
691	        if (owner.getMembershipLevel() > cap) {
692	            owner.setMembershipLevel(cap);
693	        }
694	    }
695	
696	    /**
697	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
698	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
699	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
700	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
701	     * shares a last name and postcode computes the same identifier and therefore the same household.
702	     *
703	     * @param lastName the last name of the household
704	     * @param postcode the postcode of the household, possibly {@code null}
705	     * @return the 12-character upper-case hex household identifier
706	     */
707	    private String computeHouseholdId(String lastName, String postcode) {
708	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
709	        try {
710	            byte[] digest = MessageDigest.getInstance("SHA-256")
711	                .digest(key.getBytes(StandardCharsets.UTF_8));
712	            StringBuilder hex = new StringBuilder(12);
713	            for (int i = 0; i < 6; i++) {
714	                hex.append(String.format("%02X", digest[i]));
715	            }
716	            return hex.toString();
717	        } catch (NoSuchAlgorithmException e) {
718	            throw new IllegalStateException("SHA-256 algorithm not available", e);
719	        }
720	    }
721	
722	    /**
723	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
724	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
725	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
726	     *
727	     * @param value the raw value, possibly {@code null}
728	     * @return the normalized value
729	     */
730	    private String normalizeForHousehold(String value) {
731	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
732	    }
733	
734	    /**
735	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
736	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
737	     * value yields an empty string.
738	     *
739	     * @param value the raw value, possibly {@code null}
740	     * @return the trimmed, whitespace-collapsed value
741	     */
742	    private String collapseWhitespace(String value) {
743	        if (value == null) {
744	            return "";
745	        }
746	        return value.trim().replaceAll("\\s+", " ");
747	    }
748	
749	    /**
750	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
751	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
752	     * is upper-cased, and common street-type abbreviations are expanded as whole words
753	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
754	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
755	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
756	     *
757	     * @param address the raw address value, possibly {@code null}
758	     * @return the normalized address
759	     */
760	    private String normalizeAddress(String address) {
761	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
762	        if (collapsed.isEmpty()) {
763	            return "";
764	        }
765	        String[] tokens = collapsed.split(" ");
766	        StringBuilder normalized = new StringBuilder();
767	        for (int i = 0; i < tokens.length; i++) {
768	            if (i > 0) {
769	                normalized.append(' ');
770	            }
771	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
772	        }
773	        return normalized.toString();
774	    }
775	
776	    /**
777	     * Applies the owner's address from the request, preferring the structured form over the flat one.
778	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
779	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
780	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
781	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
782	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
783	     * the structured address when present, falling back to the flat address.
784	     *
785	     * @param owner the owner being created
786	     * @param ownerFieldsDto the submitted owner fields
787	     */
788	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
789	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
790	        if (StringUtils.hasText(line1)) {
791	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
792	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
793	            owner.setAddressLine1(line1);
794	            owner.setAddressLine2(normalizedLine2);
795	            owner.setAddress(composeAddress(line1, normalizedLine2));
796	        } else {
797	            owner.setAddressLine1(null);
798	            owner.setAddressLine2(null);
799	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
800	        }
801	    }
802	
803	    /**
804	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
805	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
806	     * appended when the second line is present.
807	     *
808	     * @param line1 the normalized first address line
809	     * @param line2 the normalized second address line, or {@code null} when absent
810	     * @return the composed address string
811	     */
812	    private String composeAddress(String line1, String line2) {
813	        return line2 == null ? line1 : line1 + " " + line2;
814	    }
815	
816	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
817	    @Override
818	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
819	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
820	        if (currentOwner == null) {
821	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
822	        }
823	        currentOwner.setAddress(ownerFieldsDto.getAddress());
824	        currentOwner.setCity(ownerFieldsDto.getCity());
825	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
826	        currentOwner.setLastName(ownerFieldsDto.getLastName());
827	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
828	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
829	        this.clinicService.saveOwner(currentOwner);
830	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
831	    }
832	
833	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
834	    @Transactional
835	    @Override
836	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
837	        Owner owner = this.clinicService.findOwnerById(ownerId);
838	        if (owner == null) {
839	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
840	        }
841	        owner.setDeleted(true);
842	        this.clinicService.saveOwner(owner);
843	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
844	    }
845	
846	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
847	    @Override
848	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
849	        Owner owner = this.clinicService.findOwnerById(ownerId);
850	        if (owner == null) {
851	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
852	        }
853	        HttpHeaders headers = new HttpHeaders();
854	        Pet pet = petMapper.toPet(petFieldsDto);
855	        owner.setId(ownerId);
856	        pet.setOwner(owner);
857	        pet.getType().setName(null);
858	        this.clinicService.savePet(pet);
859	        PetDto petDto = petMapper.toPetDto(pet);
860	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
861	            .buildAndExpand(pet.getId()).toUri());
862	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
863	    }
864	
865	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
866	    @Override
867	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
868	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
869	        if (currentOwner != null) {
870	            Pet currentPet = this.clinicService.findPetById(petId);
871	            if (currentPet != null) {
872	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
873	                currentPet.setName(petFieldsDto.getName());
874	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
875	                this.clinicService.savePet(currentPet);
876	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
877	            }
878	        }
879	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
880	    }
881	
882	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
883	    @Override
884	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
885	        HttpHeaders headers = new HttpHeaders();
886	        Visit visit = visitMapper.toVisit(visitFieldsDto);
887	        Pet pet = new Pet();
888	        pet.setId(petId);
889	        visit.setPet(pet);
890	        this.clinicService.saveVisit(visit);
891	        VisitDto visitDto = visitMapper.toVisitDto(visit);
892	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
893	            .buildAndExpand(visit.getId()).toUri());
894	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
895	    }
896	
897	
898	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
899	    @Override
900	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
901	        Owner owner = this.clinicService.findOwnerById(ownerId);
902	        if (owner != null) {
903	            Pet pet = owner.getPet(petId);
904	            if (pet != null) {
905	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
906	            }
907	        }
908	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
909	    }
910	}
