208	    /**
209	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
210	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
211	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
212	     * split by taking its leading digit as the (minimal) country code.
213	     */
214	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
215	
216	    /**
217	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
218	     * single space, then the national digits grouped in threes from the left (e.g. the stored
219	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
220	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
221	     * digit string.
222	     *
223	     * @return the human-readable telephone, or the stored value when it cannot be formatted
224	     */
225	    public String getTelephoneDisplay() {
226	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
227	            return this.telephone;
228	        }
229	        String digits = this.telephone.substring(1);
230	        String countryCode = extractCountryCode(digits);
231	        String national = digits.substring(countryCode.length());
232	        StringBuilder display = new StringBuilder("+").append(countryCode);
233	        for (int i = 0; i < national.length(); i += 3) {
234	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
235	        }
236	        return display.toString();
237	    }
238	
239	    /**
240	     * Splits the country code off an E.164 digit string (country code followed by national digits,
241	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
242	     * whose required national-number length matches the remaining digits is preferred; failing that,
243	     * the leading digit is used as the country code.
244	     *
245	     * @param digits the E.164 digits without the leading {@code '+'}
246	     * @return the country-code portion of {@code digits}
247	     */
248	    private static String extractCountryCode(String digits) {
249	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
250	            String code = entry.getKey();
251	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
252	                return code;
253	            }
254	        }
255	        return digits.substring(0, 1);
256	    }
