296	        int years = Period.between(this.birthDate, asAt).getYears();
297	        if (years < 18) {
298	            return "MINOR";
299	        }
300	        if (years < 65) {
301	            return "ADULT";
302	        }
303	        return "SENIOR";
304	    }
