316	     * the last two digits of the {@link #getFiscalYear() fiscal year} of the registration date
317	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own customer code and registration
318	     * date; {@code null} when either is absent.
319	     *
320	     * @return the membership number, or {@code null} when it cannot be derived
321	     */
322	    public String getMembershipNumber() {
323	        if (this.customerCode == null || this.registrationDate == null) {
324	            return null;
325	        }
326	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
327	    }
