329	    /**
330	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
331	     * the fiscal year of the {@link #getRegistrationDate() business-day-adjusted registration date}.
332	     * The fiscal year starts on 1 July and is named by the calendar year in which it ends, so a
333	     * registration date on or after 1 July belongs to the following calendar year's fiscal year
334	     * (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an earlier date stays in the current one
335	     * (e.g. {@code 2026-06-15} is {@code 'FY26'}). Returns {@code null} when the registration date is
336	     * absent.
337	     *
338	     * @return the fiscal year, or {@code null} when the registration date is absent
339	     */
340	    public String getFiscalYear() {
341	        if (this.registrationDate == null) {
342	            return null;
343	        }
344	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
345	    }
346	
347	    /**
348	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
349	     * is named by the calendar year in which it ends: a date in July through December belongs to the
350	     * next calendar year's fiscal year, while January through June stays in the current one.
351	     *
352	     * @param date the date to classify
353	     * @return the fiscal year as a four-digit calendar year
354	     */
355	    private static int fiscalYearOf(LocalDate date) {
356	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
357	    }
358	
359	    /**
360	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
361	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
362	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
363	     *
364	     * @return the Luhn check digit, or {@code null} when the customer code is absent
365	     */
366	    public Integer getCheckDigit() {
367	        if (this.customerCode == null) {
368	            return null;
369	        }
370	        int sum = 0;
371	        boolean dbl = true;
372	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
373	            char c = this.customerCode.charAt(i);
374	            if (c < '0' || c > '9') {
375	                continue;
376	            }
377	            int d = c - '0';
378	            if (dbl) {
379	                d *= 2;
380	                if (d > 9) {
381	                    d -= 9;
382	                }
383	            }
384	            sum += d;
385	            dbl = !dbl;
386	        }
387	        return (10 - (sum % 10)) % 10;
388	    }
389	
390	    /**
391	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
392	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
393	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
394	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
395	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
396	     * tenure, the tenure points are never awarded at create time.
397	     *
398	     * @return the membership points, a non-negative integer
399	     */
400	    public Integer getMembershipPoints() {
401	        int points = 0;
402	        boolean hasEmail = this.email != null && !this.email.isBlank();
403	        if (hasEmail) {
404	            points += 2;
405	        }
406	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
407	        if (hasNoNamesakes) {
408	            points += 1;
409	        }
410	        if (this.householdSize != null && this.householdSize >= 3) {
411	            points += 2;
412	        }
413	        Long tenureFiscalYears = getTenureFiscalYears();
414	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
415	            points += 3;
416	        }
417	        return points;
418	    }
419	
420	    /**
421	     * The owner's numeric membership level. This is normally derived from the
422	     * {@link #getMembershipPoints() membership points} (see {@link #deriveMembershipLevel()}), but a
423	     * household-level cap applied at create time may store a lower value here; when such a capped level
424	     * has been stored it is returned in preference to the derived one.
425	     *
426	     * @return the membership level, an integer from 1 to 4
427	     */
428	    public Integer getMembershipLevel() {
429	        if (this.membershipLevel != null) {
430	            return this.membershipLevel;
431	        }
432	        return deriveMembershipLevel();
433	    }
434	
435	    public void setMembershipLevel(Integer membershipLevel) {
436	        this.membershipLevel = membershipLevel;
437	    }
438	
439	    /**
440	     * The owner's numeric membership level derived purely from the {@link #getMembershipPoints()
441	     * membership points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and
442	     * level 4 for 6 or more points. This is the uncapped level, before any household-level cap.
443	     *
444	     * @return the derived membership level, an integer from 1 to 4
445	     */
446	    public Integer deriveMembershipLevel() {
447	        int points = getMembershipPoints();
448	        if (points <= 1) {
449	            return 1;
450	        }
451	        if (points <= 3) {
452	            return 2;
453	        }
454	        if (points <= 5) {
455	            return 3;
456	        }
457	        return 4;
458	    }
459	
460	    /**
461	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
462	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
463	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
464	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
465	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
466	     * yet.
467	     *
468	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
469	     */
470	    public Long getTenureFiscalYears() {
471	        if (this.registrationDate == null) {
472	            return null;
473	        }
474	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
475	    }
476	
477	    /**
478	     * The owner's locality, the canonical region string. Once the owner has a
479	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
480	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
481	     * source of truth. Before the customer code is assigned (for example while a create is still
482	     * validating the postcode) it falls back to the region the code will be built from: the
483	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
484	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
485	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
486	     *
487	     * @return the canonical region string, or {@code 'UNKNOWN'}
488	     */
489	    public String getLocality() {
490	        if (this.customerCode != null) {
491	            int dash = this.customerCode.indexOf('-');
492	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
493	        }
494	        return deriveRegion();
495	    }
496	
497	    /**
498	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
499	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
500	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
501	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
502	     *
503	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
504	     */
505	    public String getTimezone() {
506	        return REGION_TIMEZONE.get(getLocality());
507	    }
508	
509	    /**
510	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
511	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
512	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
513	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
514	     * the same region for known cities but disambiguates cities that share a name.
515	     *
516	     * @return the canonical region string, or {@code 'UNKNOWN'}
517	     */
518	    private String deriveRegion() {
519	        String region = regionFromPostcode();
520	        if (region != null) {
521	            return region;
522	        }
523	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
524	    }
525	
526	    /**
527	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
528	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
529	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
530	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
531	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
532	     * owner's region, telephone and last name. Call this once at create time and store the result via
533	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
534	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
535	     *
536	     * @return the assembled customer code
537	     */
538	    public String buildCustomerCode() {
539	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
540	    }
541	
542	    /**
543	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
544	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
545	     *
546	     * @param value the value to hash
547	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
548	     */
549	    private static String sha256Hex8(String value) {
550	        try {
551	            byte[] digest = MessageDigest.getInstance("SHA-256")
552	                .digest(value.getBytes(StandardCharsets.UTF_8));
553	            StringBuilder hex = new StringBuilder(8);
554	            for (int i = 0; i < 4; i++) {
555	                hex.append(String.format("%02X", digest[i]));
556	            }
557	            return hex.toString();
558	        }
559	        catch (NoSuchAlgorithmException e) {
560	            throw new IllegalStateException("SHA-256 algorithm not available", e);
561	        }
562	    }
563	
564	    /**
565	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
566	     * absent, not a 4-digit number, or in no known range.
567	     *
568	     * @return the matching region, or {@code null}
569	     */
570	    private String regionFromPostcode() {
571	        if (this.postcode == null) {
572	            return null;
573	        }
574	        int value;
575	        try {
576	            value = Integer.parseInt(this.postcode.trim());
577	        }
578	        catch (NumberFormatException ex) {
579	            return null;
580	        }
581	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
582	            int[] range = entry.getValue();
583	            if (value >= range[0] && value <= range[1]) {
584	                return entry.getKey();
585	            }
586	        }
587	        return null;
588	    }
589	
590	    /**
591	     * The owner's preferred contact channel, derived from the owner's details. Returns
592	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
593	     *
594	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
595	     */
596	    public String getContactPreference() {
597	        boolean hasEmail = this.email != null && !this.email.isBlank();
598	        return hasEmail ? "EMAIL" : "PHONE";
599	    }
600	
601	    /**
602	     * The owner's identity key, the single derived value used for duplicate detection. It is the
603	     * lower-case SHA-256 hex digest (64 characters) of the owner's normalized telephone, lower-cased
604	     * email (empty when absent) and the {@linkplain Soundex#encode(String) Soundex} of its last name,
605	     * joined with {@code '|'} ({@code sha256hex('<telephone>|<lowerEmail>|<soundex(lastName)>')}); any
606	     * absent ({@code null}) component contributes an empty string before hashing. Two owners are
607	     * duplicates exactly when their whole identity keys are equal, so two owners sharing a last name
608	     * (and its Soundex) and postcode but carrying different telephones differ here and are both
609	     * allowed (the second is flagged a soft match rather than rejected).
610	     *
611	     * @return the derived identity key, a 64-character lower-case hex string
612	     */
613	    public String getIdentityKey() {
614	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
615	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
616	        String raw = normalizedTelephone + "|" + lowerEmail + "|" + Soundex.encode(this.getLastName());
617	        return sha256HexLower(raw);
618	    }
619	
620	    /**
621	     * The full lower-case SHA-256 hex digest (64 characters) of the given value's UTF-8 bytes, the
622	     * form the {@linkplain #getIdentityKey() identity key} takes.
623	     *
624	     * @param value the value to hash
625	     * @return the 64-character lower-case hex SHA-256 digest
626	     */
627	    private static String sha256HexLower(String value) {
628	        try {
629	            byte[] digest = MessageDigest.getInstance("SHA-256")
630	                .digest(value.getBytes(StandardCharsets.UTF_8));
631	            StringBuilder hex = new StringBuilder(digest.length * 2);
632	            for (byte b : digest) {
633	                hex.append(String.format("%02x", b));
634	            }
635	            return hex.toString();
636	        }
637	        catch (NoSuchAlgorithmException e) {
638	            throw new IllegalStateException("SHA-256 algorithm not available", e);
639	        }
640	    }
641	
642	    public String getHouseholdId() {
643	        return this.householdId;
644	    }
645	
646	    public void setHouseholdId(String householdId) {
647	        this.householdId = householdId;
648	    }
649	
650	    public Integer getNamesakeCount() {
651	        return this.namesakeCount;
652	    }
653	
654	    public void setNamesakeCount(Integer namesakeCount) {
655	        this.namesakeCount = namesakeCount;
656	    }
657	
658	    public Integer getHouseholdSize() {
659	        return this.householdSize;
660	    }
661	
662	    public void setHouseholdSize(Integer householdSize) {
663	        this.householdSize = householdSize;
664	    }
665	
666	    public String getPostcode() {
667	        return this.postcode;
668	    }
669	
670	    public void setPostcode(String postcode) {
671	        this.postcode = postcode;
672	    }
673	
674	    public Boolean getBulkSignupWarning() {
675	        return this.bulkSignupWarning;
676	    }
677	
678	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
679	        this.bulkSignupWarning = bulkSignupWarning;
680	    }
681	
682	    public Boolean getPossibleDuplicate() {
683	        return this.possibleDuplicate;
684	    }
685	
686	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
687	        this.possibleDuplicate = possibleDuplicate;
688	    }
689	
690	    public Integer getPossibleDuplicateOf() {
691	        return this.possibleDuplicateOf;
692	    }
693	
694	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
695	        this.possibleDuplicateOf = possibleDuplicateOf;
696	    }
697	
698	    /**
699	     * Whether this owner has been soft-deleted. A newly created owner is not deleted
700	     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
701	     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
702	     *
703	     * @return whether the owner has been soft-deleted
704	     */
705	    public boolean isDeleted() {
706	        return this.deleted;
707	    }
708	
709	    public void setDeleted(boolean deleted) {
710	        this.deleted = deleted;
711	    }
712	
713	    /**
714	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
715	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
716	     */
717	    @PrePersist
718	    void onCreate() {
719	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
720	    }
721	
722	    /**
723	     * Resolves the effective registration date and rolls it onto a business day. An absent
724	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
725	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
726	     * holiday: starting from the effective date, the date advances one day at a time while it lands
727	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
728	     * non-holiday business day. A date already on a business day is returned unchanged.
729	     *
730	     * <p>This is the single definition of both the defaulting and the business-day roll, used
731	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
732	     * stamps the owner and by the create endpoint that counts owners per business day.
733	     *
734	     * @param supplied the registration date from the request, or {@code null} when none was supplied
735	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
736	     */
737	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
738	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
739	        while (!isBusinessDay(effective)) {
740	            effective = effective.plusDays(1);
741	        }
742	        return effective;
743	    }
744	
745	    /**
746	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
747	     */
748	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
749	        LocalDate.of(2026, 1, 1),
750	        LocalDate.of(2026, 1, 26),
751	        LocalDate.of(2026, 4, 25),
752	        LocalDate.of(2026, 12, 25),
753	        LocalDate.of(2026, 12, 28));
754	
755	    /**
756	     * A business day is any date that is neither a weekend day nor a listed public holiday.
757	     */
758	    private static boolean isBusinessDay(LocalDate date) {
759	        DayOfWeek day = date.getDayOfWeek();
760	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
761	    }
762	
763	    protected Set<Pet> getPetsInternal() {
764	        if (this.pets == null) {
765	            this.pets = new HashSet<>();
766	        }
767	        return this.pets;
768	    }
769	
770	    protected void setPetsInternal(Set<Pet> pets) {
771	        this.pets = pets;
772	    }
773	
774	    public List<Pet> getPets() {
775	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
776	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
777	        return Collections.unmodifiableList(sortedPets);
778	    }
779	
780	    public void setPets(List<Pet> pets) {
781	        this.pets = new HashSet<>(pets);
782	    }
783	
784	    public void addPet(Pet pet) {
785	        getPetsInternal().add(pet);
786	        pet.setOwner(this);
787	    }
788	
789	    /**
790	     * Return the Pet with the given name, or null if none found for this Owner.
791	     *
792	     * @param name to test
793	     * @return true if pet name is already in use
794	     */
795	    public Pet getPet(String name) {
796	        return getPet(name, false);
797	    }
798	
799	    /**
800	     * Return the Pet with the given name, or null if none found for this Owner.
801	     *
802	     * @param name to test
803	     * @return true if pet name is already in use
804	     */
805	    public Pet getPet(String name, boolean ignoreNew) {
806	        name = name.toLowerCase();
807	        for (Pet pet : getPetsInternal()) {
808	            if (!ignoreNew || !pet.isNew()) {
809	                String compName = pet.getName();
810	                compName = compName.toLowerCase();
811	                if (compName.equals(name)) {
812	                    return pet;
813	                }
814	            }
815	        }
816	        return null;
817	    }
818	
819	    public Pet getPet(Integer petId) {
820	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
821	    }
822	
823	    @Override
824	    public String toString() {
825	        return new ToStringCreator(this)
826	
827	            .append("id", this.getId())
828	            .append("new", this.isNew())
829	            .append("lastName", this.getLastName())
830	            .append("firstName", this.getFirstName())
831	            .append("address", this.address)
832	            .append("city", this.city)
833	            .append("telephone", this.telephone)
834	            .toString();
835	    }
836	}
